            root_url,
            risk.severity("medium"), 
            risk.title(f"FOUND ${root_url} 存在CVE_2017_15236漏洞"), 
            risk.titleVerbose("CVE_2017_15236漏洞"), 
            risk.type("身份伪造"), 
            risk.typeVerbose("配置错误"), 
            risk.details({"tiandy_CVE_2017_15236_poc_res":true}),             
            )
    }
}



root_url = cli.String("root_url")
ip, port, err = str.ParseStringToHostPort(root_url)
